-- 单条消息 → 紧凑单行（tool 结果截断放宽到 1000 字符）
local function msg_line(msg)
  if type(msg) ~= "table" then return tostring(msg) end
  local role = msg.role or "?"
  local parts = { "[" .. role .. "]" }
  if msg.tool_call_id then parts[#parts + 1] = "(" .. msg.tool_call_id .. ")" end
