-- 裸 lua/luac（无参数或仅行尾注释）= 交互式 REPL，永久阻塞等 stdin。
-- 注: `(组)?` 可选捕获组合在此环境不可靠，先剥离行尾注释再匹配。
local function guard_command(cmd)
  if type(cmd) ~= "string" then return nil, "command must be a string" end
  local stripped = cmd:gsub("%s*#.*$", "")
