  end
  for seg in (cmd .. "|"):gmatch("(.-)|") do
    for _, g in ipairs(GUARDS) do
      if seg:match(g.pat) then
        return nil, "rejected by guard: " .. g.hint .. " (command: " .. cmd:sub(1, 120) .. ")"
      end
    end
  end
  return true
end

